sp_widget.client_script:
function ($timeout) {
  var c = this;
  c.darkness = "";

  if (!c.options.c_color || !c.options.c_color.length) {
    c.options.c_color = '#ffd32a'; 
  }

  c.majors = new Array(12);
  c.minors = new Array(60);

  // Initialize clock baseline using the corrected server-side instance time data
  var serverTimeBaseline = c.data.instanceTimeMs || new Date().getTime();
  var localClientHandshakePoint = performance.now(); 

  (function tick() {
    // Track precise millisecond differentials using high-resolution performance counters
    var clientTimeElapsed = performance.now() - localClientHandshakePoint;
    var preciseInstanceTime = serverTimeBaseline + clientTimeElapsed;

    // Bind current instance time snapshot into the moment parser layer
    c.date = moment(preciseInstanceTime); 

    $timeout(tick, 1000);
  })();
}

sp_widget.css:
.medical-clock-container {
  width: 100%;
  max-width: 400px;
  max-height: 400px;
  padding: 1.2em;
  margin: auto;
  background: #cfd8dc; 
  border-radius: 50%;
  box-shadow: inset 0 4px 10px rgba(0,0,0,0.35), 0 12px 36px rgba(0,0,0,0.4);
}
.square {
  position: relative;
  width: 100%;
  height: 0;
  padding-bottom: 100%;
}
.medical-svg {
  filter: drop-shadow(0px 8px 16px rgba(0,0,0,0.45));
}
.medical-face {
  fill: #2d3436; 
  stroke: #1c2833;
  stroke-width: 2px;
}
.ecg-pulse {
  fill: none;
  stroke: #2ecc71;
  stroke-width: 1.4;
  stroke-dasharray: 120;
  stroke-dashoffset: 120;
  animation: pulse-run 2.2s linear infinite;
  opacity: 0.9;
  filter: drop-shadow(0px 0px 1.5px #2ecc71);
}
@keyframes pulse-run {
  0% { stroke-dashoffset: 120; }
  50% { stroke-dashoffset: 0; }
  100% { stroke-dashoffset: -120; }
}
.minor {
  stroke: #b2bec3; 
  stroke-width: 0.6;
}
.major {
  stroke: #ffffff; 
  stroke-width: 1.6;
}
.second {
  stroke-width: 0.9;
}
.text-label {
  color: #2c3e50 !important;
  font-weight: 700;
  letter-spacing: 0.05em;
}

sp_widget.link:
function (scope, $element, attrs) {
  var element = $element[0];
  cacheElementSize(scope, element);

  $(window).on('resize', onWindowResize);
  setTimeout(onWindowResize, 5);

  function cacheElementSize(scope, element) {
    var elem = scope.elem = {};
    elem.w = element.offsetWidth;
    elem.h = element.offsetHeight;
    return elem;
  }

  function onWindowResize() {
    var elem = scope.elem;
    var isSizeChanged = elem.w != element.offsetWidth || elem.h != element.offsetHeight;
    if (isSizeChanged) {
      elem = cacheElementSize(scope, element);
      var w = Math.min(elem.h, elem.w);
      var clock = element.firstChild;
      if (clock && clock.style) {
        clock.style.width = w + "px";
      }
    }
  }
}

sp_widget.script:
(function() {
  data.isValid = false;
  data.status = "";
  data.recordNum = "DOS0001034";

  // 1. Channel current lab instance time via your exact implementation method
  var gdtInstance = new GlideDateTime();
  data.instanceTimeMs = gdtInstance.getNumericValue(); 

  // 2. Query target Dose Log record using verified scoped application table namespace
  var logTable = 'x_snc_trackmed_dose_log'; 
  var gr = new GlideRecord(logTable);

  if (gr.isValid()) {
    gr.addQuery('dose_log_id', data.recordNum); 
    gr.query();

    if (gr.next()) {
      data.isValid = true;
      data.status = gr.getValue('status'); // Values: 'Taken' or 'Not taken'
    }
  } else {
    gs.addErrorMessage("Target table identity '" + logTable + "' could not be resolved.");
  }
})();
